// Package sdkgen renders the server catalogues the JavaScript SDK mirrors.
package sdkgen

import (
	"fmt"
	"reflect"
	"sort"
	"strings"

	"revoked/util"
)

const header = "// Generated by `go run ./cmd/gen-sdk` from the server's catalogues. Do not edit.\n\n"

// Files maps each generated file name to its content.
func Files() map[string]string {
	return map[string]string{
		"codes.ts":  errorCodes(),
		"events.ts": webhookEvents(),
	}
}

func errorCodes() string {
	seen := map[string]bool{}
	v := reflect.ValueOf(util.Errors)
	for i := 0; i < v.NumField(); i++ {
		if e, ok := v.Field(i).Interface().(util.AppError); ok && e.ErrorCode != "" {
			seen[e.ErrorCode] = true
		}
	}
	codes := make([]string, 0, len(seen))
	for c := range seen {
		codes = append(codes, c)
	}
	sort.Strings(codes)

	var b strings.Builder
	b.WriteString(header)
	b.WriteString("export const ERROR_CODES = [\n")
	for _, c := range codes {
		fmt.Fprintf(&b, "  '%s',\n", c)
	}
	b.WriteString("] as const;\n\n")
	b.WriteString("/** An error code the server is known to send. */\n")
	b.WriteString("export type KnownErrorCode = (typeof ERROR_CODES)[number];\n")
	return b.String()
}

func webhookEvents() string {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("export const WEBHOOK_EVENT_TYPES = [\n")
	for _, e := range util.WebhookEventTypes {
		fmt.Fprintf(&b, "  { type: '%s', group: '%s', noisy: %t },\n", e.Type, e.Group, e.Noisy)
	}
	b.WriteString("] as const;\n\n")
	b.WriteString("/** A webhook event type the server is known to send. */\n")
	b.WriteString("export type KnownWebhookEventType = (typeof WEBHOOK_EVENT_TYPES)[number]['type'];\n\n")
	fmt.Fprintf(&b, "export const WEBHOOK_SIGNATURE_HEADER = '%s';\n", util.WebhookSignatureHeader)
	fmt.Fprintf(&b, "export const WEBHOOK_EVENT_ID_HEADER = '%s';\n", util.WebhookEventIdHeader)
	fmt.Fprintf(&b, "export const WEBHOOK_EVENT_TYPE_HEADER = '%s';\n", util.WebhookEventTypeHeader)
	fmt.Fprintf(&b, "export const WEBHOOK_SECRET_PREFIX = '%s';\n", util.WebhookSecretPrefix)
	return b.String()
}
